103	where
104	    Client: ObjectClient + Send + Sync,
105	    Prefetcher: Prefetch,
106	{
107	    async fn new(lookup: LookedUp, flags: i32, pid: u32) -> Self {
108	        metrics::increment_gauge!("fs.current_handles", 1.0, "type" => "unassigned");
109	        FileHandleState::Created { lookup, flags, pid }
110	    }
111	
112	    async fn new_write_handle(
113	        lookup: &LookedUp,
114	        ino: InodeNo,
115	        flags: i32,
116	        pid: u32,
117	        fs: &S3Filesystem<Client, Prefetcher>,
118	    ) -> Result<FileHandleState<Client, Prefetcher>, Error> {
119	        if flags & libc::O_ACCMODE == libc::O_RDONLY {
120	            return Err(err!(libc::EBADF, "file handle is not open for writes"));
121	        }
122	
123	        let is_truncate = flags & libc::O_TRUNC != 0;
124	        let handle = fs
125	            .superblock
126	            .write(
127	                &fs.client,
128	                ino,
129	                lookup.inode.parent(),
130	                pid,
131	                fs.config.allow_overwrite,
132	                is_truncate,
133	            )
134	            .await
135	            .start_writing()?;
136	        let key = lookup.inode.full_key();
137	        let handle = match fs.uploader.put(&fs.bucket, key).await {
138	            Err(e) => {
139	                return Err(err!(libc::EIO, source:e, "put failed to start"));
140	            }
141	            Ok(request) => FileHandleState::Write(UploadState::InProgress { request, handle }),
142	        };
143	        metrics::increment_gauge!("fs.current_handles", 1.0, "type" => "write");
144	        Ok(handle)
145	    }
146	
147	    async fn new_read_handle(
148	        lookup: &LookedUp,
149	        flags: i32,
150	        pid: u32,
151	        fs: &S3Filesystem<Client, Prefetcher>,
152	    ) -> Result<FileHandleState<Client, Prefetcher>, Error> {
153	        if flags & libc::O_WRONLY != 0 {
154	            return Err(err!(libc::EBADF, "file handle is not open for reads",));
155	        }
156	        if !lookup.stat.is_readable {
157	            return Err(err!(
158	                libc::EACCES,
159	                "objects in flexible retrieval storage classes are not accessible",
160	            ));
161	        }
162	        lookup.inode.start_reading()?;
163	        let full_key = lookup.inode.full_key().to_owned();
164	        let object_size = lookup.stat.size as u64;
165	        let etag = match &lookup.stat.etag {
166	            None => return Err(err!(libc::EBADF, "no E-Tag for inode {}", lookup.inode.ino())),
167	            Some(etag) => ETag::from_str(etag).expect("E-Tag should be set"),
168	        };
169	        let request = fs
170	            .prefetcher
171	            .prefetch(fs.client.clone(), &fs.bucket, &full_key, object_size, etag.clone());
172	        let handle = FileHandleState::Read { request, pid };
173	        metrics::increment_gauge!("fs.current_handles", 1.0, "type" => "read");
174	        Ok(handle)
175	    }
176	}
