+#[derive(Debug)]
+struct DirHandle {
+    #[allow(unused)]
+    ino: InodeNo,
+    handle: ReaddirHandle,
+    offset: AtomicI64,
+    last_response: AsyncMutex<Option<(i64, Vec<DirectoryEntry>)>>,
+}
+
+impl DirHandle {
+    fn offset(&self) -> i64 {
+        self.offset.load(Ordering::SeqCst)
+    }
+
+    fn next_offset(&self) {
+        self.offset.fetch_add(1, Ordering::SeqCst);
+    }
+}
