+
+        // Create an inode with "corrupted" metadata, i.e.
+        // checksum not matching ino + full key.
+        let parent_ino = FUSE_ROOT_INODE;
+        let bad_checksum = Crc32c::new(42);
+        let inode = Inode {
+            inner: Arc::new(InodeInner {
+                ino: 42,
+                parent: parent_ino,
+                name: file_name.into(),
+                full_key: file_name.into(),
